+    private final float tokensWeightThreshold;
+    private final boolean onlyScorePrunedTokens;
+
+    public TokenPruningConfig() {
+        this(DEFAULT_TOKENS_FREQ_RATIO_THRESHOLD, DEFAULT_TOKENS_WEIGHT_THRESHOLD, false);
+    }
