+        if (fieldName == null) {
+            throw new ParsingException(parser.getTokenLocation(), "No fieldname specified for query");
+        }
+
+        var qb = new WeightedTokensQueryBuilder(fieldName, tokens, tokenPruningConfig);
+        qb.queryName(queryName);
+        qb.boost(boost);
+        return qb;
+    }
+}
