+            .putNull("cluster.remote." + CLUSTER_ALIAS + ".seeds")
+            .putNull("cluster.remote." + CLUSTER_ALIAS + ".proxy_address");
+        clusterAdmin().updateSettings(new ClusterUpdateSettingsRequest().persistentSettings(builder)).get();
+    }
