+        assertThat(tmpDir.getFileName().toString(), startsWith("elasticsearch-"));
+    }
+
+    public void testTempDirWindows() throws Exception {
+        Path baseTmpDir = createTempDir();
+        sysprops.put("os.name", "Windows 10");
