+                    if (indexHasPayloads) {
+                        // Skip payloadLength block:
+                        pforUtil.skip(payIn);
+
+                        // Skip payloadBytes block:
+                        int numBytes = payIn.readVInt();
+                        payIn.seek(payIn.getFilePointer() + numBytes);
+                    }
+
+                    if (indexHasOffsets) {
+                        pforUtil.skip(payIn);
+                        pforUtil.skip(payIn);
+                    }
+                    toSkip -= BLOCK_SIZE;
+                }
+                refillPositions();
+                payloadByteUpto = 0;
+                posBufferUpto = 0;
