+            posBufferUpto++;
+            posPendingCount--;
+            return position;
+        }
+
+        @Override
+        public int startOffset() {
+            return startOffset;
+        }
+
+        @Override
+        public int endOffset() {
+            return endOffset;
+        }
+
+        @Override
+        public BytesRef getPayload() {
+            if (payloadLength == 0) {
+                return null;
+            } else {
+                return payload;
+            }
+        }
+
+        @Override
+        public long cost() {
+            return docFreq;
+        }
+    }
