+package org.elasticsearch.index.codec.postings;
+
+import org.apache.lucene.store.DataInput;
+import org.apache.lucene.store.DataOutput;
+
+import java.io.IOException;
+
+// Inspired from https://fulmicoton.com/posts/bitpacking/
+// Encodes multiple integers in a long to get SIMD-like speedups.
+// If bitsPerValue <= 8 then we pack 8 ints per long
+// else if bitsPerValue <= 16 we pack 4 ints per long
+// else we pack 2 ints per long
+final class ForUtil {
+
+    static final int BLOCK_SIZE = 128;
+    private static final int BLOCK_SIZE_LOG2 = 7;
+
+    private static long expandMask32(long mask32) {
+        return mask32 | (mask32 << 32);
+    }
+
+    private static long expandMask16(long mask16) {
+        return expandMask32(mask16 | (mask16 << 16));
+    }
+
+    private static long expandMask8(long mask8) {
+        return expandMask16(mask8 | (mask8 << 8));
+    }
+
+    private static long mask32(int bitsPerValue) {
+        return expandMask32((1L << bitsPerValue) - 1);
+    }
+
+    private static long mask16(int bitsPerValue) {
+        return expandMask16((1L << bitsPerValue) - 1);
+    }
+
+    private static long mask8(int bitsPerValue) {
+        return expandMask8((1L << bitsPerValue) - 1);
+    }
+
+    private static void expand8(long[] arr) {
+        for (int i = 0; i < 16; ++i) {
+            long l = arr[i];
+            arr[i] = (l >>> 56) & 0xFFL;
+            arr[16 + i] = (l >>> 48) & 0xFFL;
+            arr[32 + i] = (l >>> 40) & 0xFFL;
+            arr[48 + i] = (l >>> 32) & 0xFFL;
+            arr[64 + i] = (l >>> 24) & 0xFFL;
+            arr[80 + i] = (l >>> 16) & 0xFFL;
+            arr[96 + i] = (l >>> 8) & 0xFFL;
+            arr[112 + i] = l & 0xFFL;
+        }
+    }
+
+    private static void expand8To32(long[] arr) {
+        for (int i = 0; i < 16; ++i) {
+            long l = arr[i];
+            arr[i] = (l >>> 24) & 0x000000FF000000FFL;
+            arr[16 + i] = (l >>> 16) & 0x000000FF000000FFL;
+            arr[32 + i] = (l >>> 8) & 0x000000FF000000FFL;
+            arr[48 + i] = l & 0x000000FF000000FFL;
+        }
+    }
+
+    private static void collapse8(long[] arr) {
+        for (int i = 0; i < 16; ++i) {
+            arr[i] = (arr[i] << 56) | (arr[16 + i] << 48) | (arr[32 + i] << 40) | (arr[48 + i] << 32) | (arr[64 + i] << 24) | (arr[80 + i]
+                << 16) | (arr[96 + i] << 8) | arr[112 + i];
+        }
+    }
+
+    private static void expand16(long[] arr) {
+        for (int i = 0; i < 32; ++i) {
+            long l = arr[i];
+            arr[i] = (l >>> 48) & 0xFFFFL;
+            arr[32 + i] = (l >>> 32) & 0xFFFFL;
+            arr[64 + i] = (l >>> 16) & 0xFFFFL;
+            arr[96 + i] = l & 0xFFFFL;
+        }
+    }
+
+    private static void expand16To32(long[] arr) {
+        for (int i = 0; i < 32; ++i) {
+            long l = arr[i];
+            arr[i] = (l >>> 16) & 0x0000FFFF0000FFFFL;
+            arr[32 + i] = l & 0x0000FFFF0000FFFFL;
+        }
+    }
+
+    private static void collapse16(long[] arr) {
+        for (int i = 0; i < 32; ++i) {
+            arr[i] = (arr[i] << 48) | (arr[32 + i] << 32) | (arr[64 + i] << 16) | arr[96 + i];
+        }
+    }
+
+    private static void expand32(long[] arr) {
