+                        payIn.seek(payIn.getFilePointer() + numBytes);
+                    }
+
+                    if (indexHasOffsets) {
+                        pforUtil.skip(payIn);
+                        pforUtil.skip(payIn);
+                    }
+                    toSkip -= BLOCK_SIZE;
+                }
+                refillPositions();
+                payloadByteUpto = 0;
+                posBufferUpto = 0;
+                while (posBufferUpto < toSkip) {
+                    if (indexHasPayloads) {
+                        payloadByteUpto += (int) payloadLengthBuffer[posBufferUpto];
+                    }
+                    posBufferUpto++;
+                }
+            }
