+                    CodecUtil.writeIndexHeader(payOut, PAY_CODEC, VERSION_CURRENT, state.segmentInfo.getId(), state.segmentSuffix);
+                }
+            } else {
+                posDeltaBuffer = null;
+                payloadLengthBuffer = null;
+                offsetStartDeltaBuffer = null;
