+            Arrays.fill(lastSkipDocPointer, lastDocFP);
+            if (fieldHasPositions) {
+                Arrays.fill(lastSkipPosPointer, lastPosFP);
+                if (fieldHasOffsets || fieldHasPayloads) {
+                    Arrays.fill(lastSkipPayPointer, lastPayFP);
+                }
+            }
