+    }
+
+    static void writeImpacts(CompetitiveImpactAccumulator acc, DataOutput out) throws IOException {
+        Collection<Impact> impacts = acc.getCompetitiveFreqNormPairs();
+        Impact previous = new Impact(0, 0);
