+        assertNotNull(validationException);
+
+        var invalidRequest3 = new PutInferenceModelAction.Request(TASK_TYPE, null, BYTES, X_CONTENT_TYPE);
+        validationException = invalidRequest3.validate();
+        assertNotNull(validationException);
