+        try (var response = request.execute().actionGet(60, TimeUnit.SECONDS)) {
+            assertThat(response.isRunning(), is(false));
+            assertThat(response.columns(), equalTo(List.of(new ColumnInfo("sum(pause_me)", "long"))));
