+        assertThat((String) rolloverResponseMap.get("new_index"), startsWith(".ds-lazy-ds-"));
+        assertThat((String) rolloverResponseMap.get("new_index"), endsWith("-000002"));
+        assertThat(rolloverResponseMap.get("lazy"), equalTo(true));
