+        // snapshot API fails on master failover
+        assertThat(
+            asInstanceOf(
+                SnapshotException.class,
+                ExceptionsHelper.unwrapCause(
+                    expectThrows(ExecutionException.class, RuntimeException.class, () -> snapshotFuture.get(10, TimeUnit.SECONDS))
